import re
from typing import List, Dict, Any, Optional

# ----------------------------------------------------------------------
# Helpers (assumed to be defined elsewhere but included for clarity)
# ----------------------------------------------------------------------
def node_by_title(doc: Dict[str, Any], title: str) -> Dict[str, Any]:
    """Return the node whose 'title' matches the given string."""
    return next(node for node in doc["nodes"] if node.get("title") == title)

def node_by_id(doc: Dict[str, Any], node_id: str) -> Dict[str, Any]:
    """Return the node with the specified ID."""
    return next(node for node in doc["nodes"] if node.get("node_id") == node_id)

def children(doc: Dict[str, Any], node: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Return child nodes of the given node."""
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def scope_nodes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return child nodes of the scope identified by its title."""
    return children(doc, node_by_title(doc, scope))

def table_rows(node: Dict[str, Any]) -> List[tuple]:
    """Return the rows of a table node as a list of (row_index, {column: cell}) tuples."""
    rows = []
    for i, row in enumerate(node.get("table", {}).get("rows", [])):
        row_map = {col: cell for col, cell in zip(node["table"]["columns"], row)}
        rows.append((i, row_map))
    return rows

# ----------------------------------------------------------------------
# Main functions required by the specification
# ----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return a list of all distinct objects in the given scope."""
    scope_root = node_by_title(doc, scope)          # e.g. 'Video 10331'
    obj_node = node_by_title(doc, f"Video {scope.split()[-1]}: Objects")
    obj_rows = obj_node["lines"]                     # list of string lines

    entity_list = []
    pattern = re.compile(r"Object (\d+): (.+)")
    for line in obj_rows:
        m = pattern.match(line.strip())
        if m:
            obj_id = m.group(1)
            description = m.group(2).strip()
            entity_list.append({"id": obj_id, "description": description})
    return entity_list


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the last frame number present in the motion log."""
    motion_node = node_by_title(doc, f"Video {scope.split()[-1]}: Motion log")
    rows = table_rows(motion_node)
    if not rows:
        return None
    last_frame_str = rows[-1][1]["frame"]
    try:
        return float(last_frame_str)
    except ValueError:
        return None


