# Helper parsing functions
# ----------------------------------------------------------------------
OBJECT_LINE_RE = re.compile(r"Object (\d+): (.+)")
EVENT_LINE_RE = re.compile(r"Frame (\d+): Object (\d+)(?: goes (?:in|out) of scene| enters the scene| exits the scene| collides with Object (\d+))", re.IGNORECASE)

def parse_object_line(line: str) -> Optional[tuple]:
    m = OBJECT_LINE_RE.match(line.strip())
    if m:
        return m.group(1), m.group(2).strip()
    return None

def parse_event_line(line: str) -> Optional[dict]:
    """Return a dict with keys: time, subj, kind, obj (optional)."""
    m = EVENT_LINE_RE.match(line.strip())
    if m:
        time = int(m.group(1))
        subj = m.group(2)
        rest = line.strip()[len(f"Frame {time}: Object {subj}"):]
        rest = rest.strip()
        if 'enters' in rest:
            kind = "enter"
            obj = None
        elif 'exits' in rest or 'goes out' in rest:
            kind = "exit"
            obj = None
        elif 'collides with' in rest:
            kind = "collision"
            obj = m.group(3)
        else:
            return None
        return {"time": time, "subj": subj, "kind": kind, "obj": obj}
    return None

