def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all incoming events and initial state representations."""
    scope_root = node_by_title(doc, scope)
    child_nodes = scope_nodes(doc, scope)

    # Identify relevant nodes
    objects_node = node_by_title(doc, f"Video {scope.split()[-1]}: Objects")
    events_node = node_by_title(doc, f"Video {scope.split()[-1]}: Events")
    motion_node = node_by_title(doc, f"Video {scope.split()[-1]}: Motion log")

    input_records = []

    # ---- 1. Event based arrivals ------------------------------------
    # For each 'enter' event, record its arrival at the time of entry
    events_lines = events_node["lines"]
    for line_idx, line in enumerate(events_lines):
        ev = parse_event_line(line)
        if ev and ev["kind"] == "enter":
            # Find the first motion row for this object at this time
            rows = table_rows(motion_node)
            src = [[motion_node["node_id"], rows[0][0]]]  # placeholder, substituted later
            # Find matching motion row
            for r_idx, r in rows:
                if r["object"].startswith(ev["subj"]):
                    # Check frame matches event time
                    if int(r["frame"]) == ev["time"]:
                        src = [[motion_node["node_id"], r_idx]]
                        break
            # Create input record
            input_records.append({
                "id": f"in-enter-{ev['subj']}-{ev['time']}",
                "time": float(ev["time"]),
                "kind": "enter",
                "entities": [ev["subj"]],
                "fields": {},   # no extra fields
                "src": src
            })

    # ---- 2. Initial state records ------------------------------------
    # For each object, find its first motion row (if any), and use that as an input.
    rows = table_rows(motion_node)
    first_seen = {}
    for r_idx, r in rows:
        obj_desc = r["object"].strip()
        # object description starts with id+name, find id
        m_obj = re.match(r"(\d+)", obj_desc)
        if not m_obj:
            continue
        obj_id = m_obj.group(1)
        if obj_id not in first_seen:
            # Parse numeric fields
            fields = {
                "x": float(r["x"]),
                "y": float(r["y"]),
                "vx": float(r["vx"]),
                "vy": float(r["vy"]),
                "speed": float(r["speed"])
            }
            first_seen[obj_id] = {
                "time": float(r["frame"]),
                "fields": fields,
                "src": [[motion_node["node_id"], r_idx]]
            }
    for obj_id, data in first_seen.items():
        # Ensure we don't duplicate entries for objects that entered via 'enter'
        # (these will have been handled above). We'll add all, but duplicates are okay
        # because IDs are unique by time.
        input_records.append({
            "id": f"in-init-{obj_id}-{int(data['time'])}",
            "time": data["time"],
            "kind": "state",
            "entities": [obj_id],
            "fields": data["fields"],
            "src": data["src"]
        })

    return input_records


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all recorded events produced by the process."""
    child_nodes = scope_nodes(doc, scope)
    events_node = node_by_title(doc, f"Video {scope.split()[-1]}: Events")

    outcome_records = []

    # Parse event lines for collision and exit events
    for line_idx, line in enumerate(events_node["lines"]):
        ev = parse_event_line(line)
        if not ev:
            continue
        if ev["kind"] == "collision":
            outcome_records.append({
                "time": float(ev["time"]),
                "kind": "collision",
                "entities": [ev["subj"], ev["obj"]],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })
        elif ev["kind"] == "exit":
            outcome_records.append({
                "time": float(ev["time"]),
                "kind": "exit",
                "entities": [ev["subj"]],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })

    return outcome_records


