import re
from typing import Dict, List, Tuple, Any, Optional

# ----------------------------------------------------------------------
# Helper functions (dependent on the provided helpers)
# ----------------------------------------------------------------------
def node_by_title(doc: Dict[str, Any], title: str) -> Dict[str, Any]:
    return next(node for node in doc["nodes"] if node.get("title") == title)

def node_by_id(doc: Dict[str, Any], node_id: str) -> Dict[str, Any]:
    return next(node for node in doc["nodes"] if node.get("node_id") == node_id)

def children(doc: Dict[str, Any], node: Dict[str, Any]) -> List[Dict[str, Any]]:
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def scope_nodes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    return children(doc, node_by_title(doc, scope))

def table_rows(node: Dict[str, Any]) -> List[Tuple[int, Dict[str, str]]]:
    rows: List[Tuple[int, Dict[str, str]]] = []
    table = node.get("table", {})
    cols = table.get("columns", [])
    for idx, row in enumerate(table.get("rows", [])):
        rows.append((idx, {c: v for c, v in zip(cols, row)}))
    return rows

# ----------------------------------------------------------------------
# Parsing helpers
# ----------------------------------------------------------------------
OBJECT_LINE_RE = re.compile(r"Object (\d+):\s+(.+)$")
EVENT_PATTERNS: List[Tuple[re.Pattern, str]] = [
    # enter
    (re.compile(r"Frame (\d+): Object (\d+) enters the scene"), "enter"),
    # exit
    (re.compile(r"Frame (\d+): Object (\d+) exits the scene"), "exit"),
    # collision
    (re.compile(r"Frame (\d+): Object (\d+) collides with Object (\d+)"), "collision"),
    # initial view
    (re.compile(r"Frame (\d+): Object (\d+) is in view when the video begins"), "initial"),
    # optional: goes in/out
    (re.compile(r"Frame (\d+): Object (\d+) goes in? of scene"), "enter"),
    (re.compile(r"Frame (\d+): Object (\d+) goes out of scene"), "exit"),
]

def parse_event_line(line: str) -> Optional[Dict[str, Any]]:
    for pat, kind in EVENT_PATTERNS:
        m = pat.search(line)
        if m:
            if kind == "collision":
                time, subj, obj = int(m.group(1)), m.group(2), m.group(3)
                return {"time": time, "kind": kind, "subj": subj, "obj": obj}
            else:  # enter, exit, initial
                time, subj = int(m.group(1)), m.group(2)
                return {"time": time, "kind": kind, "subj": subj}
    return None

# ----------------------------------------------------------------------
# Main specification functions
# ----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return a list of all distinct objects in the given scope."""
    obj_node_title = f"{scope}: Objects"
    obj_node = node_by_title(doc, obj_node_title)
    entity_list = []
    for line in obj_node.get("lines", []):
        m = OBJECT_LINE_RE.match(line.strip())
        if m:
            obj_id, desc = m.group(1), m.group(2).strip()
            entity_list.append({"id": obj_id, "description": desc})
    return entity_list


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the last frame number present in the motion log."""
    motion_node_title = f"{scope}: Motion log"
    motion_node = node_by_title(doc, motion_node_title)
    rows = table_rows(motion_node)
    if not rows:
        return None
    last_frame_str = rows[-1][1]["frame"]
    try:
        return float(last_frame_str)
    except ValueError:
        return None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all input records for the scope."""
    inputs: List[Dict[str, Any]] = []

    # locate relevant nodes
    obj_node = node_by_title(doc, f"{scope}: Objects")
    events_node = node_by_title(doc, f"{scope}: Events")
    motion_node = node_by_title(doc, f"{scope}: Motion log")

    motion_rows = table_rows(motion_node)

    # Build a mapping from object id to its first motion row (for initial/enter states)
    first_motion: Dict[str, Tuple[int, Dict[str, str]]] = {}
    for idx, row in motion_rows:
        obj_desc = row["object"].strip()
        m = re.match(r"(\d+)", obj_desc)
        if not m:
            continue
        obj_id = m.group(1)
        if obj_id not in first_motion:
            first_motion[obj_id] = (idx, row)

    # Keep track of objects already handled via enter/initial to avoid duplicates
    handled: set = set()

    # parse events
    for line_idx, line in enumerate(events_node.get("lines", [])):
        ev = parse_event_line(line)
        if not ev:
            continue
        subj = ev["subj"]
        time = float(ev["time"])
        # locate the motion row for this object at this time (if exists)
        motion_row_idx = None
        fields: Optional[Dict[str, Any]] = None
        if subj in first_motion:
            # search for the row matching the time
            for ridx, rrow in motion_rows:
                if re.match(rf"^{subj}", rrow["object"]):
                    if int(rrow["frame"]) == int(time):
                        motion_row_idx = ridx
                        fields = {
                            "x": float(rrow["x"]),
                            "y": float(rrow["y"]),
                            "vx": float(rrow["vx"]),
                            "vy": float(rrow["vy"]),
                            "speed": float(rrow["speed"]),
                        }
                        break

        src: List[List[Any]] = [[events_node["node_id"], line_idx]]
        if motion_row_idx is not None:
            src.append([motion_node["node_id"], motion_row_idx])

        if ev["kind"] == "enter":
            # entering from outside: input
            inputs.append({
                "id": f"in-enter-{subj}-{int(ev['time'])}",
                "time": time,
                "kind": "enter",
                "entities": [subj],
                "fields": fields if fields else {},
                "src": src,
            })
            handled.add(subj)
        elif ev["kind"] == "initial":
            # present at start: input
            inputs.append({
                "id": f"in-initial-{subj}-{int(ev['time'])}",
                "time": time,
                "kind": "initial",
                "entities": [subj],
                "fields": fields if fields else {},
                "src": src,
            })
            handled.add(subj)
        # collisions and exits are outcomes, not inputs

    # For any object that appears in motion log but is not handled (unlikely), we skip.
    return inputs


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all outcome records for the scope."""
    outcomes: List[Dict[str, Any]] = []

    events_node = node_by_title(doc, f"{scope}: Events")

    for line_idx, line in enumerate(events_node.get("lines", [])):
        ev = parse_event_line(line)
        if not ev:
            continue
        time = float(ev["time"])
        src = [[events_node["node_id"], line_idx]]

        if ev["kind"] == "collision":
            outcomes.append({
                "time": time,
                "kind": "collision",
                "entities": [ev["subj"], ev["obj"]],
                "value": None,
                "src": src,
            })
        elif ev["kind"] == "exit":
            outcomes.append({
                "time": time,
                "kind": "exit",
                "entities": [ev["subj"]],
                "value": None,
                "src": src,
            })
        # initial and enter are not outcomes

    return outcomes


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return constants explicitly stated in the scope (none for CLEVRER)."""
    return {}
